/// Ensure the cache directory exists.
fn ensure_dir(&self) -> Result<()> {
    fs::create_dir_all(&self.root)
        .with_context(|| format!("Failed to create cache directory {:?}", self.root))
}

/// Write a file atomically using the write-to-temp-then-rename pattern.
///
/// Writes content to a temporary file in the same directory, then
/// renames it into place. This prevents readers from ever observing
/// a partially-written file during concurrent access.
fn atomic_write(path: &Path, content: &[u8]) -> Result<()> {
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let seq = COUNTER.fetch_add(1, Ordering::Relaxed);
    let tmp_name = format!(
        "{}.tmp.{}.{}",
        path.file_name()
            .unwrap_or_default()
            .to_string_lossy(),
        std::process::id(),
        seq,
    );
    let tmp_path = path.with_file_name(tmp_name);
    fs::write(&tmp_path, content)
        .with_context(|| format!("Failed to write temp file {:?}", tmp_path))?;
    fs::rename(&tmp_path, path).with_context(|| {
        let _ = fs::remove_file(&tmp_path);
        format!("Failed to rename {:?} to {:?}", tmp_path, path)
    })?;
    Ok(())
}

